  content.innerHTML=`<div class="panel reports-panel"><div class="panel-heading"><div><h2>Жалобы на пользователей</h2><p>Проверь описание и доказательства. При подтверждении выбери меру.</p></div></div>${table(['Дата','Кто пожаловался','На кого','Описание','Доказательство','Статус','Решение'],accountRows.map(r=>`<tr><td>${new Date(r.created_at).toLocaleString('ru-RU')}</td><td>${esc(r.reporter)}</td><td><b>${esc(r.target)}</b></td><td class="report-description">${esc(r.description)}</td><td>${r.evidence_path?`<button class="text-btn" data-action="view-report-evidence" data-id="${esc(r.id)}">Открыть</button>`:'—'}</td><td>${status(statusText(r.status))}</td><td>${r.status==='pending'?`${r.targetRole!=='admin'?`<button class="text-btn" data-action="report-block" data-id="${esc(r.id)}">Блокировать</button> `:''}${r.targetRole==='seller'?`<button class="text-btn" data-action="report-remove-seller" data-id="${esc(r.id)}">Запретить торговлю</button> `:''}<button class="text-btn" data-action="report-reject" data-id="${esc(r.id)}">Нет нарушений</button>`:'—'}</td></tr>`))}${accountRows.length?'':'<p class="empty-state">Жалоб на аккаунты пока нет.</p>'}</div><div class="panel reports-panel"><div class="panel-heading"><div><h2>Споры по заказам</h2><p>Открой переписку, проверь обстоятельства и вынеси решение.</p></div></div>${table(['Дата','Покупатель','Продавец','Товар','Сумма','Причина','Статус','Действия'],disputeRows.map(d=>`<tr><td>${new Date(d.created_at).toLocaleString('ru-RU')}</td><td>${esc(d.buyer)}</td><td>${esc(d.seller)}</td><td>${esc(d.order?.listing_title||'Заказ')}</td><td>${Number(d.order?.gross_amount||0).toLocaleString('ru-RU')} ₽</td><td class="report-description">${esc(d.reason)}</td><td>${status(statusText(d.status))}</td><td><button class="text-btn" data-action="open-dispute" data-id="${esc(d.id)}">Открыть чат и рассмотреть</button></td></tr>`))}${disputeRows.length?'':'<p class="empty-state">Споров по заказам пока нет.</p>'}</div>`;
